function init(p) {
  return { price: p.start };
}
function decide(s, p, st) {
  if (s.see === 1) st.price *= 1 + p.step;
  if (s.see === 0) st.price *= 1 - p.step;
  return st.price;
}

function init(p) {
  return { price: p.start, fine: 0 };
}
function decide(s, p, st) {
  if (s.see === 1) st.price *= st.fine ? 1 + p.step : 2;
  if (s.see === 0) { st.price *= st.fine ? 1 - p.step : 0.5; st.fine = 1; }
  return st.price;
}
